// =====================================================================
//  BIỂN BÁO VUI TRƯỚC CỔNG — ảnh do chính người chơi gửi (ảnh tự chế, để đùa),
//  nhúng thẳng vào file (data URL, không tải từ ngoài). Biển đứng bên trái lối vào,
//  quay về phía người đi tới; cột sơn sọc đỏ trắng, khung kim loại, đèn nhỏ sáng về đêm.
//  Hai bên là đôi cột câu đối (kiểu trụ biểu ở cổng tam quan) với lời đùa người chơi tự đặt.
// =====================================================================
function buildGateSign(G) {
  const { THREE, util: U, scene } = G;
  const W = G.world, GB = G.build;
  if (!W || !GB) return;
  const { C, box, cyl, sph } = GB;

  // vị trí: trên nền đất nện bên trái lối đi, cách cổng tam quan ~4,6 m; hơi xoay về giữa lối
  const SX = -3.8, SZ = 35.6, YAW = Math.atan2(-SX, 60 - SZ);
  const BW = 1.5, BH = 2.0, BY = 2.25;        // ảnh 3:4, tâm cao 2,25 m (mép dưới 1,25 m: khách đi qua không đụng đầu)
  const PX = 0.7, PZ = -0.115;                 // hai cột cách tâm ±0,7 m, đứng sau mặt khung (không lấn lên ảnh)
  const y0 = G.heightAt(SX, SZ);

  // ---------- Khung, cột, đế (gộp một mesh màu đỉnh) ----------
  const B = U.batch();
  for (const sx of [-1, 1]) {
    const x = sx * PX;
    box(B, x, 0.08, PZ, 0.3, 0.16, 0.3, 0x9a9184, { j: 0.04 });                     // đế bê tông
    cyl(B, x, 0.16 + 1.6, PZ, 0.055, 0.055, 3.2, 0x8c9096, 8, { j: 0.02 });         // cột thép
    for (let k = 0; k < 8; k++)                                                         // sọc đỏ trắng liền nhau tới mép khung
      cyl(B, x, 0.35 + k * 0.12, PZ, 0.062, 0.062, 0.12, k % 2 ? 0xf1ede4 : 0xd2322a, 8, { j: 0.02 });
  }
  box(B, 0, BY, -0.03, BW + 0.12, BH + 0.12, 0.05, 0x3a3e44, { j: 0.03 });              // khung + mặt sau
  box(B, 0, BY + BH / 2 + 0.08, 0.02, BW + 0.2, 0.05, 0.16, 0x2e3237, { j: 0.03 });     // mái che nhỏ trên đỉnh
  box(B, 0, BY + BH / 2 + 0.03, 0.12, 0.16, 0.05, 0.08, 0xf4e2b8, { j: 0 });            // bóng đèn nhỏ
  // hai cột câu đối hai bên (thu nhỏ từ trụ biểu cổng tam quan): đế đá, thân vàng đất, mũ, búp sen
  const CX = 1.12, CW = 0.56, CD = 0.42, CZ = -0.06;
  for (const sx of [-1, 1]) {
    const x = sx * CX;
    box(B, x, 0.15, CZ, CW + 0.16, 0.3, CD + 0.14, C.stoneD);
    box(B, x, 1.95, CZ, CW, 3.3, CD, C.ochre);
    box(B, x, 3.67, CZ, CW + 0.16, 0.14, CD + 0.14, C.ridge);
    box(B, x, 3.83, CZ, 0.36, 0.18, 0.3, C.ochreD);
    sph(B, x, 4.14, CZ, 0.2, C.ochre, 8, 6, { s: [1, 1.35, 1] });
    B.add(new THREE.ConeGeometry(0.08, 0.26, 6), C.ochreD, { p: [x, 4.5, CZ] });
  }
  const frame = B.mesh(G.mats.vc);
  frame.position.set(SX, y0, SZ); frame.rotation.y = YAW; frame.updateMatrix();
  scene.add(frame);

  // ---------- Mặt ảnh ----------
  const tex = new THREE.Texture();
  tex.colorSpace = THREE.SRGBColorSpace; tex.anisotropy = 4;
  const mat = new THREE.MeshLambertMaterial({ map: tex, emissive: 0xffffff, emissiveMap: tex, emissiveIntensity: 0.1 });
  const face = new THREE.Mesh(new THREE.PlaneGeometry(BW, BH), mat);
  face.position.set(0, BY, 0.006); face.receiveShadow = true; face.visible = false;
  frame.add(face); face.updateMatrix(); face.matrixAutoUpdate = false;
  const img = new Image();
  img.onload = () => { tex.image = img; tex.needsUpdate = true; face.visible = true; };
  img.onerror = () => console.error('[biển báo] không đọc được ảnh');
  img.src = photoData();

  // ban đêm: mặt biển sáng nhẹ như có đèn rọi, kèm quầng sáng nhỏ dưới bóng đèn
  const _c = new THREE.Vector3(0, BY + BH / 2 + 0.02, 0.14).applyMatrix4(frame.matrix);
  if (W.glows) W.glows.push({ x: _c.x, y: _c.y, z: _c.z, size: 0.9, r: 1.0, g: 0.86, b: 0.6, night: true });
  G.onUpdate(() => { const n = G.tod ? G.tod.night : 0; mat.emissiveIntensity = 0.1 + n * 0.5; }, 6);

  // ---------- Câu đối: liễn đỏ viền vàng, chữ vàng xếp dọc (cùng cỡ chữ cho cả hai vế) ----------
  const DOI = [['THÍ', 'CHỦ', 'TRẦN', 'VĂN', 'HẢI'], ['BAO', 'GIỜ', 'CÓ', 'NGƯỜI', 'YÊU', 'MỚI', 'ĐƯỢC', 'VÀO']]; // vế trái, vế phải
  const PW = 0.46, PH = 2.9, TW = 160, TH = 1008, SQ = 0.75;   // chữ ép ngang 75% cho cao, dễ đọc trên liễn hẹp
  const font = (fs) => `700 ${fs}px "Noto Serif", "Times New Roman", serif`;
  const mc = document.createElement('canvas').getContext('2d');
  let fs = 64; mc.font = font(fs);
  for (const t of DOI.flat()) while (mc.measureText(t).width * SQ > TW * 0.74 && fs > 10) { fs--; mc.font = font(fs); }
  const doiTex = (words) => U.canvasTex(TW, TH, (g, w, h) => {
    const bg = g.createLinearGradient(0, 0, 0, h); bg.addColorStop(0, '#7a1f16'); bg.addColorStop(1, '#4f120c');
    g.fillStyle = bg; g.fillRect(0, 0, w, h);
    const b = Math.round(w * 0.07);
    g.strokeStyle = '#e2b458'; g.lineWidth = b * 0.55; g.strokeRect(b * 0.6, b * 0.6, w - b * 1.2, h - b * 1.2);
    g.lineWidth = Math.max(2, b * 0.16); g.strokeRect(b * 1.35, b * 1.35, w - b * 2.7, h - b * 2.7);
    g.fillStyle = '#f6d27a'; g.textAlign = 'center'; g.textBaseline = 'middle'; g.font = font(fs);
    g.shadowColor = 'rgba(0,0,0,.45)'; g.shadowBlur = b * 0.4; g.shadowOffsetY = b * 0.12;
    const step = (h * 0.86) / words.length;
    words.forEach((t, i) => { g.save(); g.translate(w / 2, h * 0.07 + step * (i + 0.5)); g.scale(SQ, 1); g.fillText(t, 0, 0); g.restore(); });
  });
  DOI.forEach((words, i) => {
    const map = doiTex(words);
    const m = new THREE.MeshLambertMaterial({ map, emissive: 0xffffff, emissiveMap: map, emissiveIntensity: 0.2 });
    GB.signMaterials.push(m);                                     // sáng nhẹ về đêm như các biển khác
    const p = new THREE.Mesh(new THREE.PlaneGeometry(PW, PH), m);
    p.position.set((i ? 1 : -1) * CX, 1.95, CZ + CD / 2 + 0.008); p.receiveShadow = true;
    frame.add(p); p.updateMatrix(); p.matrixAutoUpdate = false;
  });

  // ---------- Vật cản (hộp bao theo hướng xoay): biển + hai cột câu đối, không chui qua dưới biển ----------
  const _v = new THREE.Vector3();
  const solid = (x0, z0, x1, z1, tag) => {
    let a = 1e9, b = 1e9, c = -1e9, d = -1e9;
    for (const [x, z] of [[x0, z0], [x1, z0], [x0, z1], [x1, z1]]) { _v.set(x, 0, z).applyMatrix4(frame.matrix); a = Math.min(a, _v.x); b = Math.min(b, _v.z); c = Math.max(c, _v.x); d = Math.max(d, _v.z); }
    G.collide.box(a, b, c, d, tag);
  };
  solid(-0.85, PZ - 0.15, 0.85, PZ + 0.15, 'sign');
  for (const sx of [-1, 1]) solid(sx * CX - (CW + 0.16) / 2, CZ - (CD + 0.14) / 2, sx * CX + (CW + 0.16) / 2, CZ + (CD + 0.14) / 2, 'sign');
  G.nav.built = false;

  // ảnh 384×512, JPEG nhúng sẵn — chỉ dùng trong trò chơi này
  function photoData() { return 'data:image/jpeg;base64,'; }
}
